    //说明是第一次设置关联对象，把是否关联对象设置为YES\n                isFirstAssociation = true;\n            }\n\n            /* establish or replace the association */\n            auto &refs = refs_result.first->second;\n            //在二级表中找key对应的内容，\n            auto result = refs.try_emplace(key, std::move(association));\n            //如果已经有内容了，没有内容上面根据association已经插入了值，所以啥也不用干\n            if (!result.second) {\n                //替换掉\n                association.swap(result.first->second);\n            }\n         //如果value为空\n        } else {\n            //通过object找对应的二级表\n            auto refs_it = associations.find(disguised);\n            // 如果有\n            if (refs_it != associations.end()) {\n                auto &refs = refs_it->second;\n                //通过key再在二级表里面找对应的内容\n                auto it = refs.find(key);\n                //如果有\n                if (it != refs.end()) {\n                    //删除掉\n                    association.swap(it->second);\n                    refs.erase(it);\n                    if (refs.size() == 0) {\n                        associations.erase(refs_it);\n\n                    }\n                }\n            }\n        }\n    }\n\n    // Call setHasAssociatedObjects outside the lock, since this\n    // will call the object's _noteAssociatedObjects method if it\n    // has one, and this may trigger +initialize which might do\n    // arbitrary stuff, including setting more associated objects.\n    if (isFirstAssociation)\n        object->setHasAssociatedObjects();\n\n    // release the old value (outside of the lock).\n    association.releaseHeldValue();\n}\n")])]),s._v(" "),a("div",{staticClass:"line-numbers-wrapper"},[a("span",{staticClass:"line-number"},[s._v("1")]),a("br"),a("span",{staticClass:"line-number"},[s._v("2")]),a("br"),a("span",{staticClass:"line-number"},[s._v("3")]),a("br"),a("span",{staticClass:"line-number"},[s._v("4")]),a("br"),a("span",{staticClass:"line-number"},[s._v("5")]),a("br"),a("span",{staticClass:"line-numb